use xiom.io;

use xiom.string;
fn main() -> Int {
  let scores: Map[Str, Int] = Map[Str, Int].new();
  let names: Vec[Str] = Vec[Str].new();

  names.push("Alice"); scores.insert("Alice", 850);
  names.push("Bob");   scores.insert("Bob", 920);
  names.push("Carol"); scores.insert("Carol", 780);
  names.push("Dave");  scores.insert("Dave", 950);
  names.push("Eve");   scores.insert("Eve", 880);

  let i = 0;
  while i < names.len() {
    let name = match names.get(i) { Some(n) => n, None => "" };
    let score = match scores.get(&name) { Some(s) => s, None => 0 };
    io.println(name + ": " + to_string(score));
    i = i + 1;
  }

  io.println("--- TOP 3 ---");
  let used: Map[Str, Bool] = Map[Str, Bool].new();
  let rank = 0;
  while rank < 3 {
    let best_name = "";
    let best_score = -1;
    let j = 0;
    while j < names.len() {
      let name = match names.get(j) { Some(n) => n, None => "" };
      let score = match scores.get(&name) { Some(s) => s, None => -1 };
      let already = used.contains(&name);
      if score > best_score & !already {
        best_score = score;
        best_name = name;
      }
      j = j + 1;
    }
    used.insert(best_name, true);
    io.println(to_string(rank + 1) + ". " + best_name + " - " + to_string(best_score));
    rank = rank + 1;
  }
  return 0;
}
